-- Intervals are also cast to VARCHAR, so that a changed interval qualifier, which only affects how
-- a day-time interval is displayed, is caught too.

# name: interval_subtype_units
SELECT INTERVAL '1 mil', INTERVAL '2 millennia', INTERVAL '1 c', INTERVAL '2 centuries', INTERVAL '1 dec', INTERVAL '2 decades', INTERVAL '1 a', INTERVAL '1 ka', INTERVAL '1 y', INTERVAL '2 yrs', INTERVAL '1 q', INTERVAL '2 qtrs', INTERVAL '1 mon', INTERVAL '2 months', INTERVAL '1 w', INTERVAL '2 wks';

# name: interval_day_time_subtype_units
SELECT INTERVAL '1 d', INTERVAL '2 days', INTERVAL '1 h', INTERVAL '2 hrs', INTERVAL '1 m', INTERVAL '2 mins', INTERVAL '1 s', INTERVAL '2 secs', INTERVAL '5 ms', INTERVAL '5 msecs', INTERVAL '5 milliseconds', INTERVAL '7 us', INTERVAL '7 usecs', INTERVAL '7 microseconds';

# name: interval_single_string_units
SELECT INTERVAL '1 month', INTERVAL '1 year', INTERVAL '1 day', INTERVAL '23 HOURS', INTERVAL '1 SECOND', INTERVAL '1.5 weeks', INTERVAL '1.5 day', CAST(INTERVAL '1 month' AS VARCHAR), CAST(INTERVAL '4 years 4 weeks 4 14' AS VARCHAR);

# name: interval_single_string_whitespace_and_weeks
SELECT INTERVAL '1 month ', INTERVAL ' 2 days ', INTERVAL '1 week', INTERVAL '3 weeks', DATEDIFF('day', TIMESTAMP '2024-01-31', TIMESTAMP '2024-01-31' + INTERVAL '1 month '), (DATE '2024-01-01', INTERVAL '1 week') OVERLAPS (DATE '2024-01-05', INTERVAL '1 week'), (DATE '2024-01-01', INTERVAL '1 week') OVERLAPS (DATE '2024-01-09', INTERVAL '1 week');

# name: interval_single_string_vs_qualifier
SELECT id, v_date + INTERVAL '1 month', v_date + INTERVAL '1' MONTH, v_date + INTERVAL '1 year', v_date + INTERVAL '1' YEAR, v_ts + INTERVAL '1.5 day', v_ts + INTERVAL '1.5' DAY FROM scalars WHERE v_date BETWEEN DATE '1900-01-01' AND DATE '2100-12-31' ORDER BY id;

# name: interval_plural_and_week_are_aliases
SELECT INTERVAL '30' MINUTES, INTERVAL '3' WEEK, INTERVAL '1' QUARTER, INTERVAL '2' HOURS, INTERVAL '30' MINUTE;

# name: interval_plural_alias_in_arithmetic
SELECT id, v_ts + INTERVAL '2' DAYS FROM scalars WHERE v_ts BETWEEN TIMESTAMP '1900-01-01' AND TIMESTAMP '2100-12-31' ORDER BY id;

# name: interval_omitted_units
SELECT INTERVAL '1 12:59:10:05', INTERVAL '1 day 12 hours 59 min 10 sec 5 milliseconds', INTERVAL '1 4 5 6', INTERVAL '1 4:5:6', INTERVAL '4:5:6 1', INTERVAL '4:5 1 2', INTERVAL '1 4:5 2', INTERVAL '28', INTERVAL '1 2', INTERVAL '00:2500:00', INTERVAL '4:5' MINUTE TO SECOND;

# name: interval_omitted_units_text
SELECT CAST(INTERVAL '1 4 5 6' AS VARCHAR), CAST(INTERVAL '4:5' MINUTE TO SECOND AS VARCHAR), CAST(INTERVAL '1 2' AS VARCHAR), CAST(INTERVAL '2500' MINUTE TO SECOND AS VARCHAR);

# name: interval_signs
SELECT INTERVAL '@ - 5 ago', INTERVAL '@ - 5 minutes ago', INTERVAL '@ 5 minutes ago', INTERVAL '@ ago -5 minutes', INTERVAL '5 minutes ago', INTERVAL '-5 minutes', INTERVAL '-1 month - 1 second', INTERVAL -'1 month - 1 second', INTERVAL -'1 month 1 second', INTERVAL -'30 00:00:01', INTERVAL -'-1 month - 1 second', INTERVAL -'-1 month 1 second';

# name: interval_signed_year_month
SELECT INTERVAL '3-3' YEAR TO MONTH, INTERVAL '3--3' YEAR TO MONTH, INTERVAL -'3-3' YEAR TO MONTH, CAST(INTERVAL '3--3' YEAR TO MONTH AS VARCHAR);

# name: interval_signed_day_to_hour
SELECT INTERVAL '-1-1' DAY TO HOUR, INTERVAL '-1 -1' DAY TO HOUR, INTERVAL '-1--1' DAY TO HOUR, INTERVAL '1- -1' DAY TO HOUR, CAST(INTERVAL '-1 -1' DAY TO HOUR AS VARCHAR);

# name: interval_year_month_qualifiers
SELECT INTERVAL '1 2' YEAR TO MONTH, INTERVALYM '1 2', INTERVAL '1y 10m' YEAR, INTERVAL '1y 10m' MONTH, INTERVAL '1y 10m' YEAR TO MONTH, INTERVAL '1y 10m', INTERVAL '2-6', INTERVAL '2 years 6 months', INTERVAL '1y 6m' YEAR TO MONTH, INTERVAL '1y 6m' DAY TO MINUTE, INTERVAL '3y 20m' YEAR TO MONTH;

# name: interval_day_time_qualifiers
SELECT INTERVAL '3 days 2 hours' HOUR, INTERVAL '1 3' HOUR TO MINUTE, INTERVAL '2 days 12 hours 15 mins' DAY TO MINUTE, INTERVAL '15 mins 20 sec' MINUTE TO SECOND, INTERVAL '1 hour 15 mins 20 sec' MINUTE TO SECOND, INTERVAL '2500' MINUTE, INTERVAL '28 days 3 hours' HOUR TO SECOND, INTERVAL '1 2' DAY TO HOUR, INTERVAL '1.5' DAY, INTERVAL '90' SECOND, INTERVAL '1 2:3' DAY TO MINUTE, INTERVAL '2:3:4' HOUR TO SECOND;

# name: interval_day_time_qualifiers_text
SELECT CAST(INTERVAL '3 days 2 hours' HOUR AS VARCHAR), CAST(INTERVAL '1 3' HOUR TO MINUTE AS VARCHAR), CAST(INTERVAL '2 days 12 hours 15 mins' DAY TO MINUTE AS VARCHAR), CAST(INTERVAL '1 hour 15 mins 20 sec' MINUTE TO SECOND AS VARCHAR), CAST(INTERVAL '28 days 3 hours' HOUR TO SECOND AS VARCHAR), CAST(INTERVAL '1 2' DAY TO HOUR AS VARCHAR), CAST(INTERVAL '90' SECOND AS VARCHAR);

# name: interval_precision
SELECT INTERVAL '2 hours 4 minutes 3.709384766 seconds' DAY TO SECOND, INTERVAL(4) '2 hours 4 minutes 3.709384766 seconds' DAY TO SECOND, INTERVAL '2 hours 4 minutes 3.709384766 seconds' DAY TO SECOND(4), INTERVAL(1) '1.2467' SECOND(2), INTERVAL '1h 3m 6s 5msecs 57us' DAY TO SECOND(4), INTERVAL '6 122.538987' MINUTE TO SECOND (5), INTERVAL '255 1.1111' MINUTE TO SECOND(3), INTERVAL '1.2467' SECOND(2);

# name: interval_keyword_precision
SELECT INTERVAL(3) '28 days 3 hours', INTERVAL(3) '28 days 3 hours 1.234567', INTERVAL(3) '28 days 3 hours 1.234567 sec', INTERVAL(3) '28 days 3.3 hours' HOUR TO SECOND, INTERVAL(3) '28 days 3.37 hours' HOUR TO SECOND, INTERVAL '1.234567 days' HOUR TO SECOND, INTERVAL(3) '1.23456789 days' HOUR TO SECOND, INTERVAL(3) '1.23456789 days' HOUR TO SECOND(2), INTERVAL(3) '01:00:01.234567', INTERVAL(2) '1 2' YEAR TO MONTH, INTERVAL(2) '1.23456 days' HOUR;

# name: interval_precision_comparisons
SELECT INTERVAL(3) '01:00:01.234567' = INTERVAL(3) '01:00:01.234567', INTERVAL(3) '01:00:01.234567' = INTERVAL '01:00:01.234567', INTERVAL(3) '01:00:01.234567' = INTERVAL '01:00:01.234567' HOUR TO SECOND(3), INTERVAL(3) '01:00:01.234567' = INTERVAL '01:00:01.234567' MINUTE TO SECOND(3);

# name: interval_precision_text
SELECT CAST(INTERVAL(3) '28 days 3 hours 1.234567' AS VARCHAR), CAST(INTERVAL '6 122.538987' MINUTE TO SECOND (5) AS VARCHAR), CAST(INTERVAL(1) '1.2467' SECOND(2) AS VARCHAR), CAST(INTERVAL(3) '28 days 3.37 hours' HOUR TO SECOND AS VARCHAR);

# name: interval_leading_field_precision
SELECT INTERVAL '28 days 3 hours' HOUR(4) / INTERVAL '27 days 3 hours' HOUR(4), INTERVAL '28 days 3 hours' HOUR(4), INTERVAL '1 2' DAY(3) TO HOUR, CAST(INTERVAL '28 days 3 hours' HOUR(4) AS VARCHAR);

# name: interval_fractional
SELECT INTERVAL '1 02:03:04:25.5', INTERVAL '10.5 minutes', INTERVAL '10.659 minutes', INTERVAL '10.3333333333333 minutes', INTERVAL '1.23456789 days' HOUR TO SECOND, INTERVAL '3.5' HOUR, INTERVAL '3' MINUTE / 1.5;

# name: interval_casts
SELECT CAST('3700 sec' AS INTERVAL), CAST(INTERVAL '4440' MINUTE AS INTERVAL), CAST(INTERVAL -'01:15' AS INTERVAL MINUTE), CAST('1 2' AS INTERVAL YEAR TO MONTH), CAST('1 2' AS INTERVALYM), CAST('01:02:03.456789' AS INTERVAL(3)), CAST('01:02:03.456789' AS INTERVAL DAY TO SECOND(2)), CAST('90 sec' AS INTERVAL SECOND(1)), '2 days'::INTERVAL HOUR;

# name: interval_casts_text
SELECT CAST(CAST(INTERVAL '4440' MINUTE AS INTERVAL) AS VARCHAR), CAST(CAST(INTERVAL -'01:15' AS INTERVAL MINUTE) AS VARCHAR), CAST(CAST('1 2' AS INTERVALYM) AS VARCHAR), CAST(CAST('2 days' AS INTERVAL HOUR) AS VARCHAR(20)), CAST((SELECT INTERVAL '24 hours') AS VARCHAR);

# name: interval_column_casts
SELECT id, CAST(v_interval AS VARCHAR), CAST(v_interval AS INTERVAL HOUR), CAST(CAST(v_interval AS INTERVAL MINUTE TO SECOND(1)) AS VARCHAR), CAST(v_interval AS INTERVAL(0)) FROM vertica_extras ORDER BY id;

# name: interval_operations
SELECT INTERVAL '28 days 3 hours' HOUR % INTERVAL '27 days 3 hours' HOUR, INTERVAL '1' HOUR + TIME '1:30', INTERVAL '23' HOUR + TIME '1:30', INTERVAL '1 DAY' + INTERVAL '1 HOUR', INTERVAL '1 DAY' - INTERVAL '1 HOUR', - INTERVAL '23 HOURS', 900 * INTERVAL '1 SECOND', 21 * INTERVAL '1 DAY', 3.5 * INTERVAL '1 HOUR', INTERVAL '1 HOUR' / 1.5, INTERVAL '1' YEAR * 2, INTERVAL '1-6' YEAR TO MONTH / 2;

# name: interval_column_operations
SELECT id, v_interval / 2, v_interval * 1.5, v_interval + INTERVAL '1' DAY, - v_interval, v_interval / INTERVAL '1' HOUR, v_time + v_interval, v_interval > INTERVAL '0' SECOND FROM vertica_extras ORDER BY id;

# name: interval_date_part
SELECT DATE_PART('month', INTERVAL '2-3' YEAR TO MONTH), DATE_PART('year', INTERVAL '2-3' YEAR TO MONTH), EXTRACT(DAY FROM INTERVAL '3 days 4 hours'), EXTRACT(EPOCH FROM INTERVAL '3 days 4 hours'), FLOOR((TIMESTAMP '2005-01-17 10:00' - TIMESTAMP '2005-01-01') / INTERVAL '7');

# name: interval_range_window
SELECT id, v_date, COUNT(*) OVER (ORDER BY v_date RANGE BETWEEN INTERVAL '1' YEAR PRECEDING AND CURRENT ROW), COUNT(*) OVER (ORDER BY v_ts RANGE BETWEEN INTERVAL '1 12' DAY TO HOUR PRECEDING AND INTERVAL '1' DAY FOLLOWING) FROM scalars WHERE v_date BETWEEN DATE '1900-01-01' AND DATE '2100-12-31' ORDER BY id;
